        .section-title .underline {
            width: 60px; height: 3px; background: var(--gold);
            margin: 10px auto;
        }

        .services-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 30px;
        }

        .service-card {
            padding: 40px;
            border: 1px solid #eee;
            transition: transform 0.3s;
            text-align: center;
            background: var(--white);
        }
        .service-card:hover { transform: translateY(-10px); border-color: var(--gold); }
        .service-card i { font-size: 2rem; color: var(--gold); margin-bottom: 15px; }

        /* Price List */
        .price-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 30px;
        }
        .price-table th, .price-table td {
            padding: 20px;
            text-align: left;
            border-bottom: 1px solid #eee;
        }
        .price-table th { background-color: #fdfbf7; }
        .price-tag { color: var(--gold); font-weight: bold; }

        /* Booking Section */
        .booking-box {
            background: var(--light);
            padding: 60px;
            border-radius: 20px;
            text-align: center;
            border: 1px solid #eee;
        }

        /* Floating WhatsApp Button (Mobile First) */
        .whatsapp-float {
            position: fixed;
            bottom: 20px;
            right: 20px;
            background-color: #25d366;
            color: white;
            padding: 15px 25px;
            border-radius: 50px;
            font-weight: bold;
            box-shadow: 0 4px 15px rgba(0,0,0,0.3);
            z-index: 9999;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        /* Responsive */
        @media (max-width: 768px) {
            header .nav-links { display: none; } /* Nascondi menu su mobile per semplicità o usa hamburger */
            .hero h1 { font-size: 2.5rem; }
            .whatsapp-float { width: calc(100% - 40px); justify-content: center; }
